class Solution {
public:
    vector<int> survivedRobotsHealths(vector<int>& positions, vector<int>& healths, string directions) {
        int n = positions.size();
        vector<int> idx(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            return positions[a] < positions[b];
        });

        vector<int> st;
        for (int i = 0; i < n; i++) {
            int robot = idx[i];
            if (directions[robot] == 'R') {
                st.push_back(robot);
            } else {
                bool survived = true;
                while (!st.empty() && directions[st.back()] == 'R') {
                    int top = st.back();
                    if (healths[top] > healths[robot]) {
                        healths[top]--;
                        survived = false;
                        break;
                    } else if (healths[top] < healths[robot]) {
                        st.pop_back();
                        healths[robot]--;
                    } else {
                        st.pop_back();
                        survived = false;
                        break;
                    }
                }
                if (survived) st.push_back(robot);
            }
        }

        vector<bool> alive(n, false);
        for (int r : st) alive[r] = true;

        vector<int> result;
        for (int i = 0; i < n; i++) {
            if (alive[i]) result.push_back(healths[i]);
        }
        return result;
    }
};
